    ("pkm4-p13", "pkm-4", P, E4, "Experts can author procedures without knowing the formal syntax."),
    ("pkm4-p14", "pkm-4", P, E4, "Expert-authored procedures must conform to the ontology's formal structure even though the expert never sees it."),
    ("pkm4-p15", "pkm-4", P, E4, "An assistant's answers must come from the organization's own procedural graph, not generic model output."),
    ("pkm4-p16", "pkm-4", P, E4, "Assistant answers must stay traceable to their source knowledge, as safety-critical use demands."),
    ("pkm4-p17", "pkm-4", P, W4, "Introduce partial automation, with expert review of its output, before handing a workflow to full automation."),
    ("pkm4-p18", "pkm-4", P, AI4, "The knowledge layer deserves as much investment as the model layer."),
