    ("pkm4-p45", "pkm-4", P, BI4, "Ontology work is refined through pilot implementations."),
    ("pkm4-p24", "pkm-4", P, BI4, "LOT requirements specification fixes the ontology's purpose, intended users and competency questions."),
    ("pkm4-p25", "pkm-4", P, BI4, "LOT implementation builds the ontology and maps real data into RDF."),
    ("pkm4-p26", "pkm-4", P, BI4, "Publication gives each term a unique URI and links terms semantically."),
    ("pkm4-p27", "pkm-4", P, BI4, "LOT maintenance keeps the ontology updated after release."),
    ("pkm4-p28", "pkm-4", P, BI4, "Ontology work runs in short repeated cycles over the LOT activities, not in one pass."),
    ("pkm4-p29", "pkm-4", P, BI4, "Release the ontology openly under a stated licence at a permanent identifier."),
    ("pkm4-p30", "pkm-4", P, P4, "Governance must cover procedural knowledge at every stage: capture, stewardship, retrieval and use."),
    ("pkm4-p31", "pkm-4", P, K4, "Managing procedural knowledge never finishes; it is kept up as a standing capability."),
