    ("pkm4-p33", "pkm-4", P, B4, "An assistant must be able to confirm a procedure was carried through to the end."),
    ("pkm4-p34", "pkm-4", P, B4, "AI support must be able to raise possible safety problems."),
    ("pkm4-p35", "pkm-4", P, B4, "AI support must be able to guide a worker in real time while a procedure is under way."),
    ("pkm4-p36", "pkm-4", P, I4, "When a workflow changes, the knowledge model carries that change to machines so their picture matches the current workflow."),
    ("pkm4-p37", "pkm-4", P, F4, "Encoded procedural knowledge must be queryable, checkable for validity and open to automated reasoning."),
    ("pkm4-p38", "pkm-4", P, W4, "One shared body of procedural knowledge serves both human workers and AI consumers."),
    ("pkm4-p39", "pkm-4", P, AI4, "Procedural knowledge reaches AI systems at run time through an integration that grounds their responses in it."),
